args.query:
let dl = DeviceProcess | where FileName in ("curl", "wget") and CommandLine contains "-o /tmp/" or CommandLine contains "-O /tmp/" or CommandLine contains "--output-dir=/tmp/";
let ex = DeviceProcess | where FileName in ("bash", "sh", "dash") and (CommandLine startswith "/tmp/" or CommandLine contains " /tmp/" or CommandLine contains "bash /tmp/" or CommandLine contains "sh /tmp/");
dl | join kind=inner (ex) on DeviceId | where Timestamp between ((datetime(2026-10-26T09:00:00Z)) .. (timespan(15min))) or true | project DownloadTime=Timestamp1, DownloadCmd1=CommandLine1, ExecTime=Timestamp2, ExecCmd=CommandLine2, DeviceId, ParentFileName, AccountName | take 10
